import React, { useCallback, useEffect, useRef, useState } from 'react';
import { useNavigate, useParams, useSearchParams } from 'react-router';

import { Categories, Sort, PizzaBlock, Skeleton, Pagination, ModalBuyPizza } from '../components';
import { useSelector } from 'react-redux';
import { selectPizzaData } from '../redux/pizza/selectors';
import { sizeImagesThinUrl, sizeImagesTraditionalUrl } from '../components/GlobalStyle';
import { useAppDispatch } from '../redux/store';
import { selectFilter } from '../redux/filter/selectors';
import {
  setActivePage,
  setCategoryId,
  setFilters,
  setFocusSearch,
  setSearchValue,
  setValue,
} from '../redux/filter/slice';
import { fetchPizzas } from '../redux/pizza/acyncActions';
import { SORT_MAP, SortType } from '../redux/filter/types';
import { setSelectedDough, setSelectedSize } from '../redux/pizza/slice';

type PizzaObj = {
  id: number;
  imgUrl: string;
  sizesTraditional: sizeImagesTraditionalUrl;
  sizesThin: sizeImagesThinUrl;
  title: string;
  engTitle: string;
  weightTraditionalBumpers: string[];
  types: number[];
  category: number;
  price: number[];
  rating: number;
  description: string;
};
const LIMIT = 4;

const Home = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { engTitle } = useParams();
  const [searchParams] = useSearchParams();

  const { items, status, selectedDough, selectedSize } = useSelector(selectPizzaData);
  const { categoryId, sort, activePage, searchValue } = useSelector(selectFilter);
  const onClickCategory = useCallback((id: number) => {
    dispatch(setCategoryId(id));
    dispatch(setActivePage(1));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onChangeActivePage = (page: number) => {
    dispatch(setActivePage(page));
  };

  const onClearSearchValue = () => {
    dispatch(setSearchValue(''));
    dispatch(setValue(''));
    dispatch(setFocusSearch(true));
  };

  const isFirstRender = useRef(true);
  const [modalPizza, setModalPizza] = useState<PizzaObj | null>(null);

  const [totalPages, setTotalPages] = useState<number>(1);

  //функция получения пицц
  const getPizzas = async () => {
    try {
      await dispatch(fetchPizzas()).unwrap();
    } catch (err) {
      console.error('Ошибка при загрузке пицц: ', err);
    }
  };

  const isSortType = (value: string | null): value is SortType => {
    return Object.values(SortType).includes(value as SortType);
  };
  // проверка на значения категорий, сортировок, активных страниц в url
  useEffect(() => {
    const isChangedCategory = Number(searchParams.get('categoryId')) !== categoryId;
    const isChangedPage = Number(searchParams.get('activePage')) !== activePage;
    const isChangedSort = searchParams.get('sort') !== sort.sortProperty;
    if (isChangedCategory || isChangedPage || isChangedSort) {
      const category = Number(searchParams.get('categoryId'));
      const pageParam = Number(searchParams.get('activePage'));
      const page = !pageParam || pageParam < 1 ? 1 : pageParam;
      const sortParam = searchParams.get('sort');
      const sortObj = isSortType(sortParam) ? SORT_MAP[sortParam] : SORT_MAP[SortType.RATING_ASC];
      dispatch(
        setFilters({
          categoryId: category,
          activePage: page,
          sort: sortObj,
        }),
      );
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => {
    if (status === 'idle') {
      getPizzas();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => {
    if (status !== 'success') return;

    // если нет engTitle — ничего не делаем
    if (!engTitle) return;

    const pizza = items.find((p: PizzaObj) => p.engTitle === engTitle);

    if (pizza) {
      setModalPizza(pizza);
      const doughParams = searchParams.get('dough');
      dispatch(setSelectedDough(doughParams === 'thin' ? 1 : 0));
      const size = Number(searchParams.get('size'));
      dispatch(setSelectedSize(size === 35 ? 3 : size === 30 ? 2 : size === 25 ? 1 : 0));
    } else {
      setModalPizza(null);
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [engTitle, items, status]);

  useEffect(() => {
    if (!engTitle) {
      setModalPizza(null);
    }
  }, [engTitle]);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    const params = new URLSearchParams();
    params.set('categoryId', String(categoryId));
    params.set('activePage', String(activePage));
    params.set('sort', sort.sortProperty);

    if (modalPizza) {
      params.set('dough', selectedDough === 1 ? 'thin' : 'traditional');
      params.set('size', ['20', '25', '30', '35'][selectedSize]);
      navigate(`/my-pizza-project/pizza/${modalPizza.engTitle}?${params.toString()}`);
    } else if (!engTitle) {
      navigate(`/my-pizza-project/?${params.toString()}`);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [categoryId, activePage, sort.sortProperty, modalPizza, selectedDough, selectedSize]);

  const openModal = (pizza: PizzaObj) => {
    setModalPizza(pizza);
    dispatch(setSelectedDough(0));
    dispatch(setSelectedSize(2));
  };

  const closeModal = () => {
    setModalPizza(null);

    const params = new URLSearchParams();
    params.set('categoryId', String(categoryId));
    params.set('activePage', String(activePage));
    params.set('sort', sort.sortProperty);

    navigate(`/my-pizza-project/?${params.toString()}`);
  };
  // Фильтр + сортировка
  const filteredPizzas = React.useMemo<PizzaObj[]>(() => {
    const sortByField = sort.sortProperty.replace('-', '');
    const sortOrder = sort.sortProperty.includes('-') ? 'desc' : 'asc';

    return (items || [])
      .filter((pizza: PizzaObj) => (categoryId === 0 ? true : pizza.category === categoryId))
      .filter(
        (pizza: PizzaObj) =>
          !searchValue || pizza.title.toLowerCase().includes(searchValue.toLowerCase()),
      )
      .sort((a: PizzaObj, b: PizzaObj) => {
        let valA: number | string = 0,
          valB: number | string = 0;
        switch (sortByField) {
          case 'price':
            valA = a.price[0];
            valB = b.price[0];
            break;
          case 'rating':
            valA = a.rating;
            valB = b.rating;
            break;
          case 'title':
            valA = a.title.toLowerCase();
            valB = b.title.toLowerCase();
            break;
          default:
            valA = 0;
            valB = 0;
        }
        if (typeof valA === 'string' && typeof valB === 'string')
          return sortOrder === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);

        return sortOrder === 'asc'
          ? (valA as number) - (valB as number)
          : (valB as number) - (valA as number);
      });
  }, [items, searchValue, sort.sortProperty, categoryId]);
  const startIndex = (activePage - 1) * LIMIT;
  const paginatedPizzas = filteredPizzas.slice(startIndex, startIndex + LIMIT);
  useEffect(() => {
    setTotalPages(Math.ceil(filteredPizzas.length / LIMIT) || 1);
  }, [filteredPizzas]);

  const skeleton = [...new Array(6)].map((_, i) => <Skeleton key={i} />);
  const pizzas = (paginatedPizzas || []).map((obj: any) => (
    <PizzaBlock key={obj.id} {...obj} onOpenModal={() => openModal(obj)} />
  ));

  return (
    <div className="container">
      <div className="content__top">
        <Categories value={categoryId} onClickCategory={onClickCategory} />
        <Sort />
      </div>

      <h2 className="content__title">Все пиццы</h2>

      {status === 'error' ? (
        searchValue && filteredPizzas.length === 0 ? (
          <div className="search__error">
            <h2>Ничего не нашлось по запросу «{searchValue}»</h2>
            <p>Попробуйте изменить запрос</p>
            <button onClick={() => dispatch(setSearchValue(''))}>Очистить</button>
          </div>
        ) : (
          <div className="content__error">
            <h2>Не удалось загрузить пиццы</h2>
            <button onClick={() => getPizzas()}>Повторить</button>
          </div>
        )
      ) : searchValue && filteredPizzas.length === 0 ? (
        <div className="search__error">
          <h2>Ничего не нашлось по запросу «{searchValue}»</h2>
          <p>Попробуйте изменить запрос</p>
          <button onClick={() => onClearSearchValue()}>Очистить</button>
        </div>
      ) : (
        <div className="content__items">{status === 'loading' ? skeleton : pizzas}</div>
      )}

      <Pagination
        totalPages={totalPages}
        activePage={activePage}
        onChangePage={onChangeActivePage}
      />

      {modalPizza && <ModalBuyPizza isOpen={true} onClose={closeModal} {...modalPizza} />}
    </div>
  );
};

export default Home;
