import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { filterSliceState, setFiltersState, Sort, SortType } from './types';

const initialState: filterSliceState = {
  searchValue: '',
  categoryId: 0,
  activePage: 1,
  value: '',
  focusSearch: false,
  sort: { name: 'популярности (по возрастанию)', sortProperty: SortType.RATING_ASC },
};

export const filterSlice = createSlice({
  name: 'filters',
  initialState,
  reducers: {
    setCategoryId(state, action: PayloadAction<number>) {
      state.categoryId = action.payload;
    },
    setSort(state, action: PayloadAction<Sort>) {
      state.sort = action.payload;
    },
    setActivePage(state, action: PayloadAction<number>) {
      state.activePage = action.payload;
    },
    setSearchValue(state, action: PayloadAction<string>) {
      state.searchValue = action.payload;
    },
    setValue(state, action: PayloadAction<string>) {
      state.value = action.payload;
    },
    setFocusSearch(state, action: PayloadAction<boolean>) {
      state.focusSearch = action.payload;
    },
    setFilters(state, action: PayloadAction<setFiltersState>) {
      if (Object.keys(action.payload).length) {
        state.categoryId = Number(action.payload.categoryId);
        state.activePage = Number(action.payload.activePage);
        state.sort = action.payload.sort;
      } else {
        state.categoryId = 0;
        state.activePage = 1;
        state.sort = { name: 'популярности (по возрастанию)', sortProperty: SortType.RATING_ASC };
      }
    },
    resetFilters(state) {
      state.categoryId = 0;
      state.activePage = 1;
      state.sort = { name: 'популярности (по возрастанию)', sortProperty: SortType.RATING_ASC };
    },
  },
});

export const {
  setCategoryId,
  setSort,
  setActivePage,
  setFilters,
  resetFilters,
  setSearchValue,
  setValue,
  setFocusSearch,
} = filterSlice.actions;

export default filterSlice.reducer;
