import { useSelector } from 'react-redux';
import { selectPizzaData } from '../../redux/pizza/selectors';

type SelectDoughProps = {
  onChangeDough: (index: number) => void;
};

export const SelectDough: React.FC<SelectDoughProps> = ({ onChangeDough }) => {
  const { selectedDough, selectedSize } = useSelector(selectPizzaData);
  const doughType = ['Традиционное', 'Тонкое'];
  return (
    <div>
      <ul className="choice">
        <div
          className="active-slide"
          style={{
            transform: `translateX(${selectedDough * 100}%)`,
            width: `${100 / doughType.length}%`,
          }}
        />
        {doughType.map((name, index) => {
          const isThin = index === 1;
          const isBlocked = isThin && selectedSize === 0 && selectedDough === 0;
          return (
            <li key={index}>
              <input
                type="radio"
                name="doughGroup"
                id={'dough-tab-' + index}
                checked={selectedDough === index}
                onChange={() => onChangeDough(index)}
                style={{ display: 'none' }}
                disabled={isBlocked}
              />
              <label htmlFor={'dough-tab-' + index} className={isBlocked ? 'blocked' : ''}>
                {name}
              </label>
            </li>
          );
        })}
      </ul>
    </div>
  );
};

